package cn.sevendays.focus;
import android.app.*;
import android.content.*;
import android.graphics.*;
import android.os.*;
import android.view.*;
import android.view.accessibility.AccessibilityNodeInfo;
import android.widget.*;
import java.lang.reflect.*;
import java.util.*;
/** Disposable native interaction checks. Never included in the release APK. */
public final class FlowChecks extends Instrumentation {
    Bundle args;Activity activity;final List<String> passed=new ArrayList<>();
    interface Work{void run()throws Exception;}
    void ui(Work w){Throwable[] error={null};runOnMainSync(()->{try{w.run();}catch(Throwable t){error[0]=t;}});if(error[0]!=null)throw new RuntimeException(error[0]);}
    void check(boolean value,String message){if(!value)throw new AssertionError(message);passed.add(message);}
    Object field(Object o,String key)throws Exception{Field f=o.getClass().getDeclaredField(key);f.setAccessible(true);return f.get(o);}
    Object invoke(String method,Class<?>[] types,Object...values)throws Exception{Method m=MainActivity.class.getDeclaredMethod(method,types);m.setAccessible(true);return m.invoke(activity,values);}
    Dialog dialog(String key)throws Exception{return (Dialog)field(activity,key);}
    Map<String,?> rows()throws Exception{return (Map<String,?>)field(activity,"homeRows");}
    View find(View v,String text){if(v instanceof TextView&&text.contentEquals(((TextView)v).getText()))return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View f=find(g.getChildAt(i),text);if(f!=null)return f;}}return null;}
    int count(View v,Class<?> type){int n=type.isInstance(v)?1:0;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)n+=count(((ViewGroup)v).getChildAt(i),type);return n;}
    void capture(String name,String sheet){ui(()->{View v=sheet==null?activity.getWindow().getDecorView():dialog(sheet).getWindow().getDecorView();Bitmap b=Bitmap.createBitmap(v.getWidth(),v.getHeight(),Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));try(java.io.FileOutputStream f=getTargetContext().openFileOutput(name,0)){b.compress(Bitmap.CompressFormat.PNG,100,f);}b.recycle();});}
    void shell(String command)throws Exception{try(ParcelFileDescriptor p=getUiAutomation(UiAutomation.FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES).executeShellCommand(command);java.io.InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(p)){byte[] b=new byte[1024];while(in.read(b)!=-1){}}}
    void connect()throws Exception{shell("settings delete secure enabled_accessibility_services");SystemClock.sleep(500);shell("settings put secure enabled_accessibility_services cn.sevendays.focus/cn.sevendays.focus.GuardService");shell("settings put secure accessibility_enabled 1");long end=SystemClock.elapsedRealtime()+30000;while(SystemClock.elapsedRealtime()<end){boolean[] alive={false};ui(()->alive[0]=GuardService.alive());if(alive[0])return;SystemClock.sleep(100);}throw new AssertionError("accessibility fixture did not connect");}
    void recreate()throws Exception{ActivityMonitor monitor=addMonitor(MainActivity.class.getName(),null,false);ui(activity::recreate);Activity next=monitor.waitForActivityWithTimeout(15000);removeMonitor(monitor);if(next==null)throw new AssertionError("recreated activity missing");activity=next;waitForIdleSync();SystemClock.sleep(250);}
    void openSingle(String raw)throws Exception{invoke("showEditor",new Class[]{String.class,String.class,String.class,boolean.class,boolean.class},"cn.sevendays.flowdraft","时间带测试",raw,false,false);}
    @Override public void onCreate(Bundle b){super.onCreate(b);args=b;start();}
    @Override public void onStart(){Bundle result=new Bundle();try{activity=startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();String mode=args.getString("mode", "ui");if(mode.equals("commit"))commit();else if(mode.equals("layout"))layout();else interactions();result.putString("stream","PASS "+passed.size()+" native flow checks\n"+String.join("\n",passed)+"\n");finish(Activity.RESULT_OK,result);}catch(Throwable t){result.putString("stream",android.util.Log.getStackTraceString(t));finish(Activity.RESULT_CANCELED,result);}}
    void interactions()throws Exception{
        long[] baseline=new long[2];FlowUi.Expansion[] expansion={null};
        ui(()->{Store s=Store.get(activity);baseline[0]=s.book.used("tv.danmaku.bili");baseline[1]=s.book.rules.get("tv.danmaku.bili").lockedUntil;check(baseline[0]==1921000L,"cover update retains exact prior usage");check(baseline[1]==s.prefs.getLong("test_original_until",-1),"cover update retains exact seven day deadline");check(rows().size()==3,"flat list contains every existing rule");check(find(activity.getWindow().getDecorView(),"今日")==null,"bottom two-tab navigation removed");LinearLayout list=(LinearLayout)field(activity,"listContainer");check(list.getChildCount()==3,"all rule rows have independent measured space");Object row=rows().get("tv.danmaku.bili");expansion[0]=(FlowUi.Expansion)field(row,"expansion");check(expansion[0].value==0,"details start collapsed");FlowUi.RemainingBand band=(FlowUi.RemainingBand)field(row,"band");check(Math.abs(band.fraction-(70*60000f-1921000)/(70*60000f))<.0001f,"remaining band represents remaining quota");invoke("toggleRow",new Class[]{String.class},"tv.danmaku.bili");});
        SystemClock.sleep(80);ui(()->{float before=expansion[0].value;invoke("toggleRow",new Class[]{String.class},"tv.danmaku.bili");check(expansion[0].value==before,"reversed expansion preserves current position");});SystemClock.sleep(1100);
        ui(()->{check(expansion[0].value==0&&expansion[0].velocity==0,"rapid reversed expansion settles closed");check(expansion[0].getImportantForAccessibility()==View.IMPORTANT_FOR_ACCESSIBILITY_NO_HIDE_DESCENDANTS,"closed details are hidden from accessibility");invoke("toggleRow",new Class[]{String.class},"tv.danmaku.bili");});SystemClock.sleep(1100);
        ui(()->{check(expansion[0].value==1,"inline expansion reaches complete height");check(find((View)field(rows().get("tv.danmaku.bili"),"actions"),"删除规则")==null,"locked rule exposes no delete action");invoke("toggleRow",new Class[]{String.class},"com.ss.android.ugc.aweme");});SystemClock.sleep(1100);
        ui(()->{check(expansion[0].value==0&&((FlowUi.Expansion)field(rows().get("com.ss.android.ugc.aweme"),"expansion")).value==1,"only the selected row stays expanded");View header=(View)field(rows().get("tv.danmaku.bili"),"header");check(header.performAccessibilityAction(R.id.action_move_down,null),"accessible reorder action performs display move");List<String> order=(List<String>)invoke("orderedPackages",new Class[]{});check(order.indexOf("tv.danmaku.bili")==1,"display move updates actual visible order");invoke("switchTab",new Class[]{int.class},1);invoke("switchTab",new Class[]{int.class},0);check(((List<?>)invoke("orderedPackages",new Class[]{})).indexOf("tv.danmaku.bili")==1,"display order persists across page rebuild");check(samePolicy(baseline),"expand and reorder preserve usage and lock deadline");invoke("moveRow",new Class[]{String.class,int.class},"tv.danmaku.bili",0);invoke("toggleRow",new Class[]{String.class},"com.ss.android.ugc.aweme");});SystemClock.sleep(400);capture("flow-home.png",null);
        ui(()->openSingle("73"));waitForIdleSync();
        ui(()->{Dialog d=dialog("editor");check(count(d.getWindow().getDecorView(),CheckBox.class)==1,"editor has one explicit lock confirmation");Button save=d.findViewById(10007);check(!save.isEnabled(),"unconfirmed quota cannot commit");CheckBox agree=d.findViewById(10002);agree.setChecked(true);check(save.isEnabled(),"one confirmation enables valid quota");EditText input=d.findViewById(10001);input.setText("1441");check(!save.isEnabled()&&!agree.isChecked(),"out-of-range number blocks save and clears consent");input.setText("73");FlowUi.TimeBand band=d.findViewById(10006);check(band.value==73,"numeric input updates time band");band.performAccessibilityAction(AccessibilityNodeInfo.ACTION_SCROLL_FORWARD,null);check(input.getText().toString().equals("78"),"accessible time band updates numeric quota");AccessibilityNodeInfo info=band.createAccessibilityNodeInfo();check(info.getRangeInfo()!=null&&info.getRangeInfo().getMax()==1440,"time band exposes actual accessible range");info.recycle();input.setText("1440");agree.setChecked(true);});capture("flow-editor.png","editor");
        ui(()->{FlowUi.TimeBand band=dialog("editor").findViewById(10006);band.setValue(0);gesture(band,-80);check(band.position<0&&band.value==0,"lower boundary resists overshoot without negative quota");});SystemClock.sleep(1400);ui(()->{FlowUi.TimeBand band=dialog("editor").findViewById(10006);check(band.scroller.isFinished()&&Math.abs(band.position)<1,"time band springs back to exact lower endpoint");band.setValue(1440);gesture(band,80);check(band.position>band.span()&&band.value==1440,"upper boundary never publishes excess quota");});SystemClock.sleep(1400);ui(()->{FlowUi.TimeBand band=dialog("editor").findViewById(10006);check(band.scroller.isFinished()&&Math.abs(band.position-band.span())<1,"time band springs back to exact upper endpoint");((EditText)dialog("editor").findViewById(10001)).setText("1440");((CheckBox)dialog("editor").findViewById(10002)).setChecked(true);});
        recreate();ui(()->{Dialog d=dialog("editor");check(d!=null&&d.isShowing()&&((EditText)d.findViewById(10001)).getText().toString().equals("1440"),"activity recreation restores uncommitted numeric draft");check(((CheckBox)d.findViewById(10002)).isChecked(),"activity recreation restores one consent state");check(!Store.get(activity).book.rules.containsKey("cn.sevendays.flowdraft"),"recreation never silently commits draft");d.dismiss();check(samePolicy(baseline),"all draft interactions preserve existing policies");});
    }
    void gesture(FlowUi.TimeBand v,float distance){long now=SystemClock.uptimeMillis();float x=v.getWidth()/2f,y=v.getHeight()/3f;MotionEvent e=MotionEvent.obtain(now,now,MotionEvent.ACTION_DOWN,x,y,0);v.onTouchEvent(e);e.recycle();for(int i=1;i<=4;i++){e=MotionEvent.obtain(now,now+i*20,MotionEvent.ACTION_MOVE,x+distance*i/4,y,0);v.onTouchEvent(e);e.recycle();}e=MotionEvent.obtain(now,now+90,MotionEvent.ACTION_UP,x+distance,y,0);v.onTouchEvent(e);e.recycle();}
    boolean samePolicy(long[] baseline){Store s=Store.get(activity);return s.book.used("tv.danmaku.bili")==baseline[0]&&s.book.rules.get("tv.danmaku.bili").lockedUntil==baseline[1];}
    void commit()throws Exception{
        connect();String p="cn.sevendays.probe.second",q="cn.sevendays.probe.third";long[] original=new long[2];List<BatchRules.Entry> entries=Arrays.asList(new BatchRules.Entry(p,"验证应用二",15),new BatchRules.Entry(q,"验证应用三",60));
        ui(()->{Store s=Store.get(activity);original[0]=s.book.used("tv.danmaku.bili");original[1]=s.book.rules.get("tv.danmaku.bili").lockedUntil;check(!s.book.rules.containsKey(p)&&!s.book.rules.containsKey(q),"batch fixture starts with two unmanaged installed apps");invoke("showBatch",new Class[]{List.class,boolean.class,String.class},entries,false,p);Map<String,EditText> inputs=(Map<String,EditText>)field(activity,"batchInputs");inputs.get(p).setText("25");inputs.get(q).setText("75");check(((Button)field(activity,"batchSave")).isEnabled()==false,"batch waits for its single consent");});waitForIdleSync();capture("flow-batch.png","batchDialog");
        recreate();ui(()->{Map<String,EditText> inputs=(Map<String,EditText>)field(activity,"batchInputs");check(inputs.get(p).getText().toString().equals("25")&&inputs.get(q).getText().toString().equals("75"),"batch recreation preserves individual quotas");check(p.equals(field(activity,"batchExpanded")),"batch recreation preserves expanded time band");CheckBox consent=(CheckBox)field(activity,"batchConsent");consent.setChecked(true);inputs.get(q).setText("76");check(!consent.isChecked(),"changing any batch quota invalidates common consent");consent.setChecked(true);Store s=Store.get(activity);String before=s.database.read();s.database.getWritableDatabase().execSQL("CREATE TRIGGER reject_flow BEFORE INSERT ON snapshot BEGIN SELECT RAISE(ABORT,'injected batch write failure'); END");try{((Button)field(activity,"batchSave")).performClick();check(dialog("batchDialog")!=null&&dialog("batchDialog").isShowing(),"failed batch retains open editable draft");check(!s.book.rules.containsKey(p)&&!s.book.rules.containsKey(q),"failed batch publishes no partial in-memory rule");check(before.equals(s.database.read()),"failed batch preserves exact durable snapshot");check(count((View)field(activity,"stage"),FlowUi.SuccessMark.class)==0,"failed batch never displays success feedback");}finally{s.database.getWritableDatabase().execSQL("DROP TRIGGER reject_flow");}Button save=(Button)field(activity,"batchSave");save.performClick();save.performClick();check(dialog("batchDialog")==null||!dialog("batchDialog").isShowing(),"successful batch closes immediately without animation wait");check(s.book.rules.get(p).minutes==25&&s.book.rules.get(q).minutes==76,"atomic batch saves individual quota values");check(s.book.rules.get(p).lockedUntil==s.book.rules.get(q).lockedUntil&&s.book.locked(p,s.now()),"batch locks all new rules at one exact deadline");check(count((View)field(activity,"stage"),FlowUi.SuccessMark.class)==1,"successful batch shows nonblocking saved feedback once");check(samePolicy(original),"batch commit preserves existing usage and deadline");Store reload=new Store(activity);try{check(reload.book.rules.get(q).minutes==76&&reload.book.rules.get(p).lockedUntil==s.book.rules.get(p).lockedUntil,"fresh Store reads complete committed batch");}finally{reload.close();}});
        SystemClock.sleep(1500);ui(()->check(count((View)field(activity,"stage"),FlowUi.SuccessMark.class)==0,"saved feedback removes itself in finite time"));
    }
    void layout()throws Exception{
        ui(()->{Store s=Store.get(activity);s.book.rules.get("tv.danmaku.bili").minutes=1440;s.book.usage.put("tv.danmaku.bili",0L);invoke("render",new Class[]{});});waitForIdleSync();
        ui(()->{Object row=rows().get("tv.danmaku.bili");TextView time=(TextView)field(row,"left");check(time.getLineCount()==1&&time.getRight()<=((View)time.getParent()).getWidth(),"24 hour remaining stays inside large-font row");TextView name=(TextView)field(row,"name");check(name.getWidth()>Ui.dp(activity,140),"large-font row preserves readable app name width");check(((TextView)field(row,"quota")).getLineCount()<=2,"large-font quota label avoids narrow vertical wrapping");openSingle("1440");});waitForIdleSync();
        ui(()->{Dialog d=dialog("editor");EditText input=d.findViewById(10001);check(input.getPaint().measureText("1440")<=input.getWidth()-input.getCompoundPaddingLeft()-input.getCompoundPaddingRight()+1,"four digit input fits at current font scale");View save=d.findViewById(10007);Rect rect=new Rect();check(save.getGlobalVisibleRect(rect)&&rect.height()==save.getHeight(),"save footer remains fully visible");check(save.getHeight()>=Ui.dp(activity,48),"save touch target remains at least 48 dp");});capture("flow-large-editor.png","editor");ui(()->dialog("editor").dismiss());capture("flow-large-home.png",null);
        ui(()->{List<BatchRules.Entry> draft=Arrays.asList(new BatchRules.Entry("cn.sevendays.probe.second","四位额度测试",1440),new BatchRules.Entry("cn.sevendays.probe.third","另一项",30));invoke("showBatch",new Class[]{List.class,boolean.class,String.class},draft,false,"");});waitForIdleSync();ui(()->{Map<String,EditText> inputs=(Map<String,EditText>)field(activity,"batchInputs");EditText input=inputs.get("cn.sevendays.probe.second");check(input.getPaint().measureText("1440")<=input.getWidth()-input.getCompoundPaddingLeft()-input.getCompoundPaddingRight()+1,"batch four digit input fits at current font scale");View save=(View)field(activity,"batchSave");Rect rect=new Rect();check(save.getGlobalVisibleRect(rect)&&rect.height()==save.getHeight(),"batch confirmation footer remains fully visible");});capture("flow-large-batch.png","batchDialog");ui(()->dialog("batchDialog").dismiss());
    }
}
